export const AEO_PAPER1_GS: PYQQuestion[] = [

  // ── TELANGANA HISTORY & CULTURE (30 Qs) ──
  { id:"aeop1_001", year:2024, subject:"general-studies", question:"Telangana became the _____ state of India on 2 June 2014:", options:["31st", "28th", "30th", "29th"], correct: 3, explanation:"Telangana became the 29th state of India when it was carved out of the existing state of Andhra Pradesh on 2 June 2014." },
  { id:"aeop1_002", year:2024, subject:"general-studies", question:"The Kakatiya dynasty ruled from their capital at:", options:["Nizamabad", "Hyderabad", "Warangal (Orugallu)", "Golkonda"], correct: 2, explanation:"The Kakatiya dynasty (1083–1323 AD) ruled from Warangal, also known as Orugallu (one stone) or Ekasila Nagaram." },
  { id:"aeop1_003", year:2024, subject:"general-studies", question:"Ramappa Temple, a UNESCO World Heritage Site, is located in:", options:["Karimnagar", "Nalgonda", "Warangal", "Mulugu district (Palampet)"], correct: 3, explanation:"Ramappa Temple (Ramalingeswara Temple) is at Palampet in Mulugu district. Built in 1213 CE under Kakatiya general Recharla Rudra, it was inscribed as UNESCO WHS in July 2021." },
  { id:"aeop1_004", year:2024, subject:"general-studies", question:"Who is called the 'Ideological Father of Telangana'?", options:["Prof. Jayashankar Sarojini Devi", "K. Chandrashekar Rao", "Burgula Ramakrishna Rao", "Marri Chenna Reddy"], correct: 0, explanation:"Prof. Marri Jayashankar (Prof. Jayashankar) is revered as the ideological father of the Telangana movement. PJTSAU is named in his honour." },
  { id:"aeop1_005", year:2024, subject:"general-studies", question:"Telangana Rashtra Samiti (TRS) was founded in:", options:["1999", "2001", "2006", "2004"], correct: 1, explanation:"TRS was founded on 27 April 2001 by K. Chandrashekar Rao to spearhead the separate Telangana statehood movement." },
  { id:"aeop1_006", year:2024, subject:"general-studies", question:"Telangana state flower is:", options:["Tangedu (Senna auriculata)", "Lotus", "Rose", "Jasmine"], correct: 0, explanation:"Tangedu (Senna auriculata) is the state flower of Telangana, prominently used in the traditional Bathukamma festival floral arrangement." },
  { id:"aeop1_007", year:2024, subject:"general-studies", question:"Telangana state animal is:", options:["Nilgai", "Tiger", "Spotted Deer (Jinka)", "Indian Bison (Gaur)"], correct: 2, explanation:"The Spotted Deer (Chital/Jinka — Axis axis) is the state animal of Telangana." },
  { id:"aeop1_008", year:2024, subject:"general-studies", question:"Telangana state bird is:", options:["Flamingo", "Palapitta (Indian Roller/Neelkanth)", "Peacock", "Great Indian Bustard"], correct: 1, explanation:"Palapitta (Indian Roller/Neelkanth — Coracias benghalensis) is the state bird of Telangana, also the state bird of Andhra Pradesh." },
  { id:"aeop1_009", year:2024, subject:"general-studies", question:"The Godavari river originates from:", options:["Himalayas", "Trimbakeshwar, Nashik (Western Ghats, Maharashtra)", "Satpura range", "Eastern Ghats"], correct: 1, explanation:"Godavari originates from Trimbakeshwar near Nashik, Maharashtra at 1,067m elevation. It is India's second-longest river and is called 'Dakshina Ganga'." },
  { id:"aeop1_010", year:2024, subject:"general-studies", question:"Nagarjunasagar-Srisailam Tiger Reserve is the largest tiger reserve in India — it spans across:", options:["Telangana and Andhra Pradesh", "Maharashtra and Telangana", "Karnataka and Telangana", "Telangana only"], correct: 0, explanation:"The Nagarjunasagar-Srisailam Tiger Reserve (3,728 sq km) spans across both Telangana (Nalgonda) and Andhra Pradesh, making it India's largest tiger reserve." },
  { id:"aeop1_011", year:2024, subject:"general-studies", question:"Pochampally Ikat sarees have GI (Geographical Indication) tag — Pochampally is in:", options:["Yadadri-Bhongir (Nalgonda) district", "Warangal", "Adilabad", "Karimnagar"], correct: 0, explanation:"Bhoodan Pochampally is in Yadadri-Bhongir district (formerly Nalgonda). It is world-famous for distinctive Pochampally Ikat silk sarees, recognised by UNESCO as a World Craft City." },
  { id:"aeop1_012", year:2024, subject:"general-studies", question:"'Mission Kakatiya' scheme in Telangana aims to:", options:["Restore and rejuvenate 46,531 minor irrigation tanks", "Build new roads", "Develop industrial corridors", "Provide housing to poor"], correct: 0, explanation:"Mission Kakatiya (launched March 2015) restores Telangana's traditional tank network — 46,531 minor irrigation tanks — to revive their irrigation, groundwater recharge, and ecosystem benefits." },
  { id:"aeop1_013", year:2024, subject:"general-studies", question:"'Mission Bhagiratha' provides:", options:["Free electricity to farmers", "Piped drinking water to every household in Telangana", "Rural road connectivity", "Housing to BPL families"], correct: 1, explanation:"Mission Bhagiratha (launched 2016) provides treated surface water through household piped connections to every rural and urban household in Telangana, addressing the chronic drinking water problem." },
  { id:"aeop1_014", year:2024, subject:"general-studies", question:"Telangana's total number of districts after October 2016 reorganisation is:", options:["10", "33", "23", "31"], correct: 1, explanation:"Telangana was reorganised from 10 to 31 districts in October 2016 (later expanded to 33) to improve administrative efficiency and bring governance closer to people." },
  { id:"aeop1_015", year:2024, subject:"general-studies", question:"Hyderabad is known as 'City of Pearls' because:", options:["Its rivers have pearl oysters", "Its government buildings are pearl-shaped", "It was a historic global pearl trading hub and still known for pearl jewellery", "It produces fresh water pearls"], correct: 2, explanation:"Hyderabad earned this title as one of the world's premier natural pearl trading centres during the Nizam era. Its Charminar area remains famous for pearl jewellery." },
  { id:"aeop1_016", year:2024, subject:"general-studies", question:"'Bathukamma' festival of Telangana is celebrated during:", options:["Dasara", "Sankranti", "Navaratri (Mahalayam/Sharadiya Navaratri) in September–October", "Diwali"], correct: 2, explanation:"Bathukamma (meaning 'Come Alive Mother Goddess') is a nine-day floral festival celebrated by Telangana women during Sharadiya Navaratri using Tangedu and seasonal flowers." },
  { id:"aeop1_017", year:2024, subject:"general-studies", question:"Kaleshwaram Lift Irrigation Scheme (KLIS) is built on which river?", options:["Musi", "Manjira", "Krishna", "Godavari"], correct: 3, explanation:"KLIS lifts water from the Godavari River at Medigadda barrage (Kaleshwaram confluence). It is the world's largest multi-stage lift irrigation project." },
  { id:"aeop1_018", year:2024, subject:"general-studies", question:"Singareni Collieries Company Ltd (SCCL) is owned by:", options:["NMDC", "Private companies", "Telangana Govt 51% + Central Govt 49%", "Central Government only"], correct: 2, explanation:"SCCL is a joint venture between Telangana State Government (51%) and Government of India/BHCL (49%). It operates the largest coalfield in South India." },
  { id:"aeop1_019", year:2024, subject:"general-studies", question:"'Dharani' portal in Telangana is related to:", options:["Farmer welfare schemes", "Integrated land records and property registration", "Water supply management", "Crop insurance"], correct: 1, explanation:"Dharani is Telangana's integrated land records management and property registration portal, launched in November 2020. It integrates pahani, registration, and mutation." },
  { id:"aeop1_020", year:2024, subject:"general-studies", question:"Telangana's capital city is:", options:["Nizamabad", "Hyderabad (joint capital with AP for 10 years)", "Karimnagar", "Warangal"], correct: 1, explanation:"Hyderabad is the capital of Telangana. Under the Andhra Pradesh Reorganisation Act 2014, Hyderabad serves as the joint capital for both Telangana and Andhra Pradesh for a period of 10 years." },
  { id:"aeop1_021", year:2024, subject:"general-studies", question:"Which district of Telangana is known as 'Rice Bowl'?", options:["Karimnagar", "Adilabad", "Mahabubnagar", "Nalgonda"], correct: 0, explanation:"Karimnagar district (and its split districts) is known as the 'Rice Bowl of Telangana' due to extensive paddy cultivation under Sriram Sagar Project canals." },
  { id:"aeop1_022", year:2024, subject:"general-studies", question:"'Rythu Bandhu' scheme provides per acre support of:", options:["₹4,000/year", "₹15,000/year", "₹6,000/year", "₹10,000/year"], correct: 3, explanation:"Rythu Bandhu (launched May 2018) provides ₹10,000 per acre per year (₹5,000 per season) as direct investment support to all land-owning farmers in Telangana." },
  { id:"aeop1_023", year:2024, subject:"general-studies", question:"'Haritha Haram' programme aims to increase Telangana's green cover to:", options:["24%", "50%", "60%", "33%"], correct: 1, explanation:"Haritha Haram targets increasing tree cover to 33% initially and ultimately 50% of Telangana's geographical area through mass plantation of saplings." },
  { id:"aeop1_024", year:2024, subject:"general-studies", question:"The Nizam's Hyderabad merged with India through:", options:["UN mediation", "Treaty signing", "Police Action (Operation Polo) — September 1948", "Referendum"], correct: 2, explanation:"Hyderabad State was integrated into India through Police Action (Operation Polo) on 17–18 September 1948 after the Nizam refused accession. Hyderabad officially merged in November 1948." },
  { id:"aeop1_025", year:2024, subject:"general-studies", question:"PJTSAU (Prof. Jayashankar Telangana State Agricultural University) is located at:", options:["Adilabad", "Warangal", "Karimnagar", "Rajendranagar, Hyderabad"], correct: 3, explanation:"PJTSAU is located at Rajendranagar, Hyderabad. It was established in 2014 after bifurcation of ANGRAU, named after Telangana activist Prof. Jayashankar." },
  { id:"aeop1_026", year:2024, subject:"general-studies", question:"Telangana shares borders with how many states?", options:["6", "5", "3", "4"], correct: 1, explanation:"Telangana shares borders with 5 states: Andhra Pradesh (south/east), Karnataka (southwest), Maharashtra (north/northwest), Chhattisgarh (northeast), and Odisha (east corner)." },
  { id:"aeop1_027", year:2024, subject:"general-studies", question:"Which Telangana district is known for turmeric production?", options:["Nizamabad", "Warangal", "Khammam", "Karimnagar"], correct: 0, explanation:"Nizamabad district is famous for turmeric production, particularly the 'Nizamabad Bulb' variety with high curcumin content. Telangana is among India's top turmeric-producing states." },
  { id:"aeop1_028", year:2024, subject:"general-studies", question:"'Warangal Fort' was built during reign of:", options:["Prataparudra II", "Betaraja", "Ganapati Deva", "Rudrama Devi"], correct: 2, explanation:"Warangal Fort (Orugallu Kota) was primarily built by Ganapati Deva (1199–1262 AD), the powerful Kakatiya ruler who also commissioned the Ramappa Temple." },
  { id:"aeop1_029", year:2024, subject:"general-studies", question:"'Namasthe Telangana' is:", options:["A government scheme", "Official Telangana State Government newspaper in Telugu", "A river project", "A tourism brand"], correct: 1, explanation:"Namasthe Telangana is the official Telugu-language daily newspaper launched by the Telangana State Government to disseminate government policies and developmental news." },
  { id:"aeop1_030", year:2024, subject:"general-studies", question:"'Rythu Bima' scheme in Telangana provides:", options:["Life insurance of ₹5 lakh for farmers — premium paid by State Govt", "Crop insurance", "Free seeds to farmers", "Land ownership documents"], correct: 0, explanation:"Rythu Bima is a group farmer life insurance scheme providing ₹5 lakh coverage to all registered farmers in Telangana. The entire premium is borne by the State Government." },

  // ── INDIAN HISTORY, POLITY & CONSTITUTION (30 Qs) ──
  { id:"aeop1_031", year:2024, subject:"general-studies", question:"The Indian Constitution came into force on:", options:["14 August 1947", "26 January 1950", "15 August 1947", "26 November 1949"], correct: 1, explanation:"The Indian Constitution came into force on 26 January 1950 (Republic Day). It was adopted by the Constituent Assembly on 26 November 1949 (Constitution Day)." },
  { id:"aeop1_032", year:2024, subject:"general-studies", question:"Fundamental Rights are enshrined in which Part of the Constitution?", options:["Part III", "Part V", "Part II", "Part IV"], correct: 0, explanation:"Fundamental Rights (Articles 12–35) are in Part III of the Indian Constitution. They are justiciable — enforceable through courts including the Supreme Court (Article 32)." },
  { id:"aeop1_033", year:2024, subject:"general-studies", question:"The 73rd Constitutional Amendment (1992) is related to:", options:["Right to Education", "Reservation for OBCs", "Panchayati Raj Institutions — giving constitutional status to PRIs", "Freedom of press"], correct: 2, explanation:"73rd Amendment gave constitutional status to PRIs, mandated three-tier Panchayati Raj, and reserved 1/3 seats for women in all PRI bodies." },
  { id:"aeop1_034", year:2024, subject:"general-studies", question:"'Gram Sabha' in Panchayati Raj consists of:", options:["All voters registered in the gram panchayat area", "Government officials", "Elected members only", "Only BPL families"], correct: 0, explanation:"Gram Sabha is the foundation of PRIs — it comprises all registered voters of the village panchayat. It meets at least twice a year and has powers to approve plans and review development works." },
  { id:"aeop1_035", year:2024, subject:"general-studies", question:"India follows which type of government?", options:["Presidential system", "Confederal system", "Unitary system", "Parliamentary federal system"], correct: 3, explanation:"India has a Parliamentary federal system — the executive (Council of Ministers) is responsible to the legislature (Parliament), with federal distribution of powers between Centre and States." },
  { id:"aeop1_036", year:2024, subject:"general-studies", question:"The Right to Education Act (2009) makes free and compulsory education a right for children aged:", options:["6–14 years", "3–10 years", "4–12 years", "5–15 years"], correct: 0, explanation:"RTE Act 2009 (Article 21-A) guarantees free and compulsory education to all children between 6 and 14 years as a fundamental right." },
  { id:"aeop1_037", year:2024, subject:"general-studies", question:"Which article of the Constitution abolishes untouchability?", options:["Article 14", "Article 21", "Article 17", "Article 15"], correct: 2, explanation:"Article 17 of the Indian Constitution abolishes untouchability and forbids its practice in any form. Its enforcement is a punishable offence under the Protection of Civil Rights Act." },
  { id:"aeop1_038", year:2024, subject:"general-studies", question:"NITI Aayog replaced Planning Commission in:", options:["2014", "2015", "2016", "2013"], correct: 1, explanation:"NITI Aayog (National Institution for Transforming India) replaced the Planning Commission on 1 January 2015. It functions as a policy think-tank promoting cooperative federalism." },
  { id:"aeop1_039", year:2024, subject:"general-studies", question:"The Directive Principles of State Policy are in which Part?", options:["Part V", "Part IV", "Part III", "Part VI"], correct: 1, explanation:"Directive Principles of State Policy (Articles 36–51) are in Part IV of the Constitution. They are non-justiciable but fundamental in governance — guidelines for state policy." },
  { id:"aeop1_040", year:2024, subject:"general-studies", question:"Indian Parliament consists of:", options:["Lok Sabha + Rajya Sabha + President", "Rajya Sabha only", "Lok Sabha only", "Lok Sabha + Rajya Sabha"], correct: 0, explanation:"Indian Parliament consists of three parts: President of India + Rajya Sabha (Council of States) + Lok Sabha (House of the People), as per Article 79 of the Constitution." },
  { id:"aeop1_041", year:2024, subject:"general-studies", question:"Right to Information (RTI) Act was enacted in:", options:["2007", "2005", "2002", "2003"], correct: 1, explanation:"RTI Act was enacted on 15 June 2005 and came into force on 12 October 2005, giving citizens the right to access information from public authorities." },
  { id:"aeop1_042", year:2024, subject:"general-studies", question:"The Green Revolution in India was primarily associated with:", options:["Vegetable production increase", "Forest conservation", "Organic farming", "HYV wheat and rice with chemical fertilizers and irrigation"], correct: 3, explanation:"Green Revolution (mid-1960s) introduced HYV semi-dwarf wheat (Lerma Rojo, Sonora 64) and rice varieties with chemical fertilizers, pesticides, and irrigation, making India food-sufficient." },
  { id:"aeop1_043", year:2024, subject:"general-studies", question:"National Food Security Act 2013 covers what percentage of population?", options:["67%", "50%", "90%", "75%"], correct: 0, explanation:"The National Food Security Act 2013 covers up to 75% of rural population and 50% of urban population (approximately 67% of total population), providing subsidised foodgrains." },
  { id:"aeop1_044", year:2024, subject:"general-studies", question:"The first Prime Minister of India was:", options:["Jawaharlal Nehru", "Sardar Vallabhbhai Patel", "B.R. Ambedkar", "Rajendra Prasad"], correct: 0, explanation:"Jawaharlal Nehru was India's first Prime Minister (August 1947 – May 1964). He served for 17 years, the longest tenure as PM." },
  { id:"aeop1_045", year:2024, subject:"general-studies", question:"'Swachh Bharat Mission' was launched on:", options:["15 August 2014", "26 January 2015", "1 April 2014", "2 October 2014"], correct: 3, explanation:"Swachh Bharat Mission was launched on 2 October 2014 (Gandhi Jayanti) by PM Modi to promote cleanliness and eliminate open defecation across India." },
  { id:"aeop1_046", year:2024, subject:"general-studies", question:"MGNREGA guarantees how many days of employment per year?", options:["150", "100", "50", "200"], correct: 1, explanation:"MGNREGA (2005) guarantees 100 days of unskilled manual work per year to every rural household whose adult members demand employment." },
  { id:"aeop1_047", year:2024, subject:"general-studies", question:"PM-KISAN provides ₹6,000/year in how many instalments?", options:["Four of ₹1,500", "Two of ₹3,000", "Three of ₹2,000", "Six of ₹1,000"], correct: 2, explanation:"PM-KISAN provides ₹6,000 per year in three equal instalments of ₹2,000 each directly to eligible farmers' bank accounts." },
  { id:"aeop1_048", year:2024, subject:"general-studies", question:"'GST' (Goods and Services Tax) was implemented from:", options:["1 July 2017", "1 January 2018", "1 April 2017", "1 March 2017"], correct: 0, explanation:"GST — India's comprehensive indirect tax reform — was implemented from 1 July 2017, replacing multiple central and state taxes with a unified 'One Nation One Tax' system." },
  { id:"aeop1_049", year:2024, subject:"general-studies", question:"The Speaker of Lok Sabha is elected by:", options:["Members of Lok Sabha", "President of India", "Prime Minister", "All MPs"], correct: 0, explanation:"The Speaker of Lok Sabha is elected by the members of the Lok Sabha from among themselves (Article 93). The Speaker presides over Lok Sabha proceedings." },
  { id:"aeop1_050", year:2024, subject:"general-studies", question:"India's Constitution is:", options:["The shortest in the world", "An unwritten constitution", "The longest written constitution in the world", "Modelled exactly on the UK Constitution"], correct: 2, explanation:"India has the world's longest written constitution. As amended, it has 448 articles in 25 parts, 12 schedules, and 5 appendices. It borrowed provisions from multiple world constitutions." },
  { id:"aeop1_051", year:2024, subject:"general-studies", question:"Who chaired the Drafting Committee of the Indian Constitution?", options:["Jawaharlal Nehru", "B.R. Ambedkar", "Rajendra Prasad", "Sardar Patel"], correct: 1, explanation:"Dr. B.R. Ambedkar chaired the Drafting Committee of the Indian Constitution and is called the 'Father of the Indian Constitution'. The Constitution was adopted on 26 November 1949." },
  { id:"aeop1_052", year:2024, subject:"general-studies", question:"Panchayati Raj system ensures governance at:", options:["State level", "National level", "Village level (grassroots)", "District and block level only"], correct: 2, explanation:"Panchayati Raj system provides democratic governance at the grassroots/village level through Gram Panchayats, ensuring people's participation in local self-governance and development." },
  { id:"aeop1_053", year:2024, subject:"general-studies", question:"The 'Demonetisation' of ₹500 and ₹1000 notes in India was announced on:", options:["8 November 2016", "8 November 2015", "15 August 2016", "2 October 2016"], correct: 0, explanation:"PM Narendra Modi announced demonetisation of ₹500 and ₹1000 notes on 8 November 2016 to combat black money, counterfeit currency, and terrorism financing." },
  { id:"aeop1_054", year:2024, subject:"general-studies", question:"Which article empowers the President to declare National Emergency?", options:["Article 356", "Article 352", "Article 360", "Article 365"], correct: 1, explanation:"Article 352 empowers the President to proclaim National Emergency (on grounds of war, external aggression, or armed rebellion) on the written advice of the Cabinet." },
  { id:"aeop1_055", year:2024, subject:"general-studies", question:"'Digital India' programme was launched in:", options:["2014", "2016", "2015", "2013"], correct: 2, explanation:"Digital India was launched on 1 July 2015, with vision to transform India into a digitally empowered society and knowledge economy through digital infrastructure, governance, and literacy." },
  { id:"aeop1_056", year:2024, subject:"general-studies", question:"Minimum age to vote in India is:", options:["25 years", "18 years", "21 years", "16 years"], correct: 1, explanation:"The voting age in India was lowered from 21 to 18 years by the 61st Constitutional Amendment Act, 1988. Article 326 now gives suffrage to all citizens above 18 years." },
  { id:"aeop1_057", year:2024, subject:"general-studies", question:"'White Revolution' (Operation Flood) in India was led by:", options:["Norman Borlaug", "M.S. Swaminathan", "Dr. Verghese Kurien", "C. Subramaniam"], correct: 2, explanation:"Operation Flood (White Revolution), led by Dr. Verghese Kurien through NDDB (1970–1996), transformed India from a milk-deficit country to the world's largest milk producer." },
  { id:"aeop1_058", year:2024, subject:"general-studies", question:"The National Human Rights Commission (NHRC) was established in:", options:["1995", "1993", "1990", "2000"], correct: 1, explanation:"NHRC was established on 12 October 1993 under the Protection of Human Rights Act, 1993. It inquires into complaints of human rights violations by State or Central Government." },
  { id:"aeop1_059", year:2024, subject:"general-studies", question:"'Make in India' initiative was launched to:", options:["Promote organic farming", "Promote imports", "Boost exports of agriculture", "Make India a global manufacturing hub and attract FDI"], correct: 3, explanation:"Make in India (launched 25 September 2014) encourages companies worldwide to manufacture in India, with the goal of creating 100 million jobs and contributing 25% of GDP through manufacturing by 2025." },
  { id:"aeop1_060", year:2024, subject:"general-studies", question:"Which body recommends Minimum Support Price (MSP) for crops?", options:["NABARD", "CACP (Commission for Agricultural Costs and Prices)", "Food Corporation of India", "Reserve Bank of India"], correct: 1, explanation:"CACP (Commission for Agricultural Costs and Prices), an advisory body under Ministry of Agriculture, recommends MSP based on production costs, market prices, and farmer welfare." },

  // ── GENERAL SCIENCE & ENVIRONMENT (25 Qs) ──
  { id:"aeop1_061", year:2024, subject:"general-studies", question:"Photosynthesis in plants produces:", options:["Glucose (food) and Oxygen", "Carbon dioxide and water", "Only oxygen", "Only glucose"], correct: 0, explanation:"Photosynthesis converts CO2 + H2O (using sunlight and chlorophyll) into glucose (C6H12O6) + O2. The equation: 6CO2 + 6H2O + light energy → C6H12O6 + 6O2." },
  { id:"aeop1_062", year:2024, subject:"general-studies", question:"Which gas makes up the largest proportion of Earth's atmosphere?", options:["Nitrogen (78%)", "Oxygen (21%)", "Carbon dioxide", "Argon"], correct: 0, explanation:"Nitrogen (N2) constitutes approximately 78% of the Earth's atmosphere, followed by Oxygen (21%), Argon (0.9%), and CO2 (0.04%)." },
  { id:"aeop1_063", year:2024, subject:"general-studies", question:"The unit of electrical power is:", options:["Ampere", "Volt", "Ohm", "Watt"], correct: 3, explanation:"The Watt (W) is the SI unit of power, named after James Watt. 1 Watt = 1 Joule/second. In electricity: Power (W) = Voltage (V) × Current (A)." },
  { id:"aeop1_064", year:2024, subject:"general-studies", question:"'Ozone layer' protects Earth from:", options:["Ultraviolet (UV) radiation", "Infrared radiation", "Visible light", "Radio waves"], correct: 0, explanation:"The stratospheric ozone layer (O3) absorbs 97–99% of the Sun's harmful UV-B and UV-C radiation, protecting life on Earth from DNA damage and skin cancer." },
  { id:"aeop1_065", year:2024, subject:"general-studies", question:"The chemical formula of water is:", options:["HO", "H2O2", "H3O", "H2O"], correct: 3, explanation:"Water's chemical formula is H2O — two hydrogen atoms covalently bonded to one oxygen atom. It is the most abundant compound on Earth's surface." },
  { id:"aeop1_066", year:2024, subject:"general-studies", question:"Which vitamin is produced by skin on exposure to sunlight?", options:["Vitamin B12", "Vitamin A", "Vitamin C", "Vitamin D"], correct: 3, explanation:"Vitamin D (cholecalciferol) is synthesised in the skin when 7-dehydrocholesterol is exposed to UV-B radiation from sunlight. It is essential for calcium absorption and bone health." },
  { id:"aeop1_067", year:2024, subject:"general-studies", question:"The speed of light in vacuum is approximately:", options:["3 × 10⁵ km/s", "3 × 10⁸ m/s", "3 × 10⁶ km/s", "3 × 10⁴ m/s"], correct: 1, explanation:"The speed of light in vacuum (c) is approximately 3 × 10⁸ m/s (299,792,458 m/s). It is the universal speed limit — nothing with mass can exceed it." },
  { id:"aeop1_068", year:2024, subject:"general-studies", question:"Which planet is known as the 'Red Planet'?", options:["Venus", "Jupiter", "Saturn", "Mars"], correct: 3, explanation:"Mars is called the Red Planet because its surface is covered with iron oxide (rust), giving it a distinctive reddish appearance. It has two small moons: Phobos and Deimos." },
  { id:"aeop1_069", year:2024, subject:"general-studies", question:"DNA stands for:", options:["Diribonucleic Acid", "Deoxyribose Nucleic Acid", "Dinucleotide Acid", "Deoxyribonucleic Acid"], correct: 3, explanation:"DNA = Deoxyribonucleic Acid. It is the hereditary material in most organisms, carrying genetic instructions for development, functioning, and reproduction." },
  { id:"aeop1_070", year:2024, subject:"general-studies", question:"The process by which solid converts directly to gas without passing through liquid state is:", options:["Evaporation", "Condensation", "Boiling", "Sublimation"], correct: 3, explanation:"Sublimation is the phase transition from solid to gas directly, without passing through the liquid state. Examples: dry ice (CO2), naphthalene (camphor balls), iodine crystals." },
  { id:"aeop1_071", year:2024, subject:"general-studies", question:"'Paris Agreement' (2015) is related to:", options:["Climate change — limiting global temperature rise below 2°C", "International trade", "Nuclear disarmament", "Food security"], correct: 0, explanation:"Paris Agreement (COP21, December 2015) is a global climate accord aiming to limit global temperature rise to well below 2°C (ideally 1.5°C) above pre-industrial levels by reducing greenhouse gas emissions." },
  { id:"aeop1_072", year:2024, subject:"general-studies", question:"Eutrophication of water bodies is caused by excess:", options:["Chlorine", "Carbon dioxide", "Fluoride", "Nitrogen and Phosphorus (from fertilizer runoff)"], correct: 3, explanation:"Eutrophication is the enrichment of water bodies with excess nutrients (N and P) from agricultural runoff (fertilizers) and sewage, causing algal blooms, oxygen depletion, and fish kills." },
  { id:"aeop1_073", year:2024, subject:"general-studies", question:"'Mangalyaan' (Mars Orbiter Mission) was launched by ISRO in:", options:["2014", "2013", "2012", "2015"], correct: 1, explanation:"India's MOM/Mangalyaan was launched on 5 November 2013 and entered Mars orbit on 24 September 2014, making India the first country to succeed in its first Mars mission." },
  { id:"aeop1_074", year:2024, subject:"general-studies", question:"Which of the following is a non-renewable energy source?", options:["Coal", "Solar energy", "Wind energy", "Hydroelectric power"], correct: 0, explanation:"Coal is a non-renewable fossil fuel that takes millions of years to form. Solar, wind, and hydroelectric are renewable energy sources that replenish naturally." },
  { id:"aeop1_075", year:2024, subject:"general-studies", question:"The human body's largest organ is:", options:["Skin", "Liver", "Brain", "Heart"], correct: 0, explanation:"The skin is the largest organ of the human body, covering about 1.5–2 sq metres surface area and weighing 3–4 kg. It protects against pathogens, regulates temperature, and enables sensation." },
  { id:"aeop1_076", year:2024, subject:"general-studies", question:"Which gas is responsible for the 'greenhouse effect'?", options:["Nitrogen", "Carbon dioxide (CO2)", "Oxygen", "Helium"], correct: 1, explanation:"CO2 is the primary greenhouse gas responsible for the enhanced greenhouse effect and climate change. Other GHGs include methane (CH4), nitrous oxide (N2O), and water vapour." },
  { id:"aeop1_077", year:2024, subject:"general-studies", question:"National Forest Policy of India (1988) targets forest/tree cover of:", options:["20%", "33%", "25%", "40%"], correct: 1, explanation:"National Forest Policy 1988 recommends maintaining 33% of India's total geographic area under forest and tree cover (currently about 24%), with 67% in hills and 20% in plains." },
  { id:"aeop1_078", year:2024, subject:"general-studies", question:"ISRO stands for:", options:["Indian Space Research Organisation", "International Space Research Organisation", "Indian Scientific Research Organisation", "Indian Satellite Research Office"], correct: 0, explanation:"ISRO (Indian Space Research Organisation) was established in 1969 with headquarters in Bengaluru. It is responsible for India's space programme, including satellites, launch vehicles, and planetary missions." },
  { id:"aeop1_079", year:2024, subject:"general-studies", question:"The chemical symbol for Gold is:", options:["Gd", "Go", "Au", "Ag"], correct: 2, explanation:"Gold's chemical symbol is Au, from the Latin word 'Aurum'. It is a precious yellow metal (atomic number 79) used in jewellery, electronics, and as a monetary standard." },
  { id:"aeop1_080", year:2024, subject:"general-studies", question:"Which organ of the body purifies blood?", options:["Lungs", "Kidney", "Heart", "Liver"], correct: 1, explanation:"Kidneys purify blood by filtering waste products (urea, creatinine, excess salts) and excess water, producing urine. Each day kidneys filter about 200 litres of blood." },
  { id:"aeop1_081", year:2024, subject:"general-studies", question:"'Biodiversity hotspot' is defined as an area with:", options:["High temperature only", "Maximum forest area", "High number of endemic species under threat of habitat loss", "Highest rainfall"], correct: 2, explanation:"A biodiversity hotspot has ≥1,500 endemic vascular plant species AND has lost ≥70% of its original habitat. India has 4 hotspots: Western Ghats, Himalayas, Indo-Burma, and Sundaland." },
  { id:"aeop1_082", year:2024, subject:"general-studies", question:"'Soil erosion' is most severe when:", options:["Soil is wet and flat", "Soil is bare (no vegetation) on sloped land with heavy rainfall", "Soil is dry and flat", "Soil is covered with vegetation"], correct: 1, explanation:"Soil erosion is most severe on bare, sloped land exposed to heavy rainfall — no vegetation means no protection from raindrop splash, surface runoff, and rill/gully formation." },
  { id:"aeop1_083", year:2024, subject:"general-studies", question:"The 'hole' in the ozone layer was first detected over:", options:["Amazon", "Himalayas", "Antarctica", "Arctic"], correct: 2, explanation:"The ozone hole (seasonal thinning) was first detected over Antarctica in 1985 by British Antarctic Survey scientists, caused primarily by CFCs (chlorofluorocarbons) from refrigerants and aerosols." },
  { id:"aeop1_084", year:2024, subject:"general-studies", question:"'Van Mahotsav' is celebrated to promote:", options:["Water conservation", "Soil conservation", "Tree plantation (celebrated in first week of July every year)", "Wildlife conservation"], correct: 2, explanation:"Van Mahotsav (Forest Festival) is celebrated annually in the first week of July to promote tree plantation and forest conservation. It was started in 1950 by K.M. Munshi, then Union Agriculture Minister." },
  { id:"aeop1_085", year:2024, subject:"general-studies", question:"Normal human body temperature is:", options:["35°C", "38°C", "36°C", "37°C (98.6°F)"], correct: 3, explanation:"Normal human body temperature is 37°C (98.6°F). Fever is generally defined as body temperature above 38°C (100.4°F). Temperature varies slightly throughout the day." },

  // ── INDIAN ECONOMY & AGRICULTURE POLICY (20 Qs) ──
  { id:"aeop1_086", year:2024, subject:"general-studies", question:"NABARD was established in:", options:["1990", "1975", "1982", "1969"], correct: 2, explanation:"NABARD (National Bank for Agriculture and Rural Development) was established on 12 July 1982 on B. Sivaraman Committee recommendations, replacing RBI's Agricultural Credit Department." },
  { id:"aeop1_087", year:2024, subject:"general-studies", question:"'Operation Flood' was related to:", options:["Fisheries", "Dairy development (White Revolution)", "Irrigation expansion", "Flood control"], correct: 1, explanation:"Operation Flood (1970–1996) was India's dairy development programme implemented by NDDB under Dr. Verghese Kurien, transforming India into the world's largest milk producer." },
  { id:"aeop1_088", year:2024, subject:"general-studies", question:"RKVY (Rashtriya Krishi Vikas Yojana) was launched in:", options:["2007-08", "2010-11", "2012-13", "2004-05"], correct: 0, explanation:"RKVY was launched in 2007-08 to incentivise states to increase public investment in agriculture with 4% annual growth target. It provides flexibility to states for agriculture development." },
  { id:"aeop1_089", year:2024, subject:"general-studies", question:"e-NAM (National Agriculture Market) was launched in:", options:["2014", "2016", "2018", "2013"], correct: 1, explanation:"e-NAM was launched on 14 April 2016, creating a pan-India electronic trading portal linking 1,000+ APMC mandis for unified national agricultural commodity trading." },
  { id:"aeop1_090", year:2024, subject:"general-studies", question:"PMFBY (Pradhan Mantri Fasal Bima Yojana) was launched in:", options:["2015", "2017", "2016", "2014"], correct: 2, explanation:"PMFBY was launched in February 2016, replacing NAIS and MNAIS. Premium rates: 2% for kharif, 1.5% for rabi, 5% for commercial crops." },
  { id:"aeop1_091", year:2024, subject:"general-studies", question:"Soil Health Card scheme was launched by PM Modi from:", options:["Suratgarh, Rajasthan", "Lucknow", "Patna", "Hyderabad"], correct: 0, explanation:"PM Modi launched the Soil Health Card scheme on 19 February 2015 from Suratgarh, Rajasthan. Cards are provided to all farmers every 2 years with soil test-based fertilizer recommendations." },
  { id:"aeop1_092", year:2024, subject:"general-studies", question:"'Kisan Credit Card' scheme was launched in:", options:["2004", "2001", "1995", "1998"], correct: 3, explanation:"KCC scheme was launched in 1998 based on R.V. Gupta Committee recommendations by NABARD to provide farmers short-term crop loans through revolving credit cards." },
  { id:"aeop1_093", year:2024, subject:"general-studies", question:"'Per Drop More Crop' is a component of which scheme?", options:["NMSA", "NHM", "RKVY", "PM Krishi Sinchai Yojana (PMKSY)"], correct: 3, explanation:"'Per Drop More Crop' is a key component of PMKSY promoting micro-irrigation (drip and sprinkler) through 55% subsidy for small/marginal farmers and 45% for others." },
  { id:"aeop1_094", year:2024, subject:"general-studies", question:"India's rank in world milk production is:", options:["Fourth", "First", "Third", "Second"], correct: 1, explanation:"India is the world's largest milk producer, contributing about 23% of global milk production. Uttar Pradesh, Rajasthan, Madhya Pradesh, Gujarat, and Andhra Pradesh are top milk-producing states." },
  { id:"aeop1_095", year:2024, subject:"general-studies", question:"Paramparagat Krishi Vikas Yojana (PKVY) promotes:", options:["Precision farming", "Organic farming in 50-acre clusters", "Contract farming", "Chemical farming"], correct: 1, explanation:"PKVY (2015) promotes organic farming in 50-acre clusters, providing ₹50,000/ha over 3 years for input production, certification, and market linkages — helping farmers shift to certified organic farming." },
  { id:"aeop1_096", year:2024, subject:"general-studies", question:"'Doubling Farmers' Income' target set by Government of India was for year:", options:["2025", "2030", "2022", "2020"], correct: 2, explanation:"PM Modi announced the goal of doubling farmers' income by 2022 (base year 2015-16) in February 2016. The Ashok Dalwai Committee was constituted to recommend strategies." },
  { id:"aeop1_097", year:2024, subject:"general-studies", question:"'National Mission for Sustainable Agriculture' (NMSA) focuses on:", options:["Industrial development", "Urban agriculture", "Climate-smart agriculture — soil health, water efficiency, organic farming", "Export promotion"], correct: 2, explanation:"NMSA (under National Action Plan on Climate Change) promotes sustainable agriculture through soil health management, micro-irrigation, integrated farming systems, and organic farming for climate resilience." },
  { id:"aeop1_098", year:2024, subject:"general-studies", question:"'Farmer Producer Organisation' (FPO) is a type of:", options:["Collective company owned by farmers for joint input procurement and marketing", "NGO", "Cooperative society only", "Government department"], correct: 0, explanation:"FPO is a producer company owned and managed by farmers. It gives them collective bargaining power, enables bulk input purchase (10–30% cheaper), and improves market access and price realisation." },
  { id:"aeop1_099", year:2024, subject:"general-studies", question:"ICAR (Indian Council of Agricultural Research) was established in:", options:["1965", "1929", "1947", "1919"], correct: 1, explanation:"ICAR was established on 16 July 1929 as the Imperial Council of Agricultural Research, renamed after independence. HQ in New Delhi, it coordinates India's agricultural research and education." },
  { id:"aeop1_100", year:2024, subject:"general-studies", question:"India's share in world cotton production is approximately:", options:["35%", "15%", "10%", "23–25%"], correct: 3, explanation:"India is the world's largest cotton producer, contributing about 23–25% of global production. Gujarat, Maharashtra, and Telangana/AP are the top cotton-producing states." },
  { id:"aeop1_101", year:2024, subject:"general-studies", question:"'Agricultural Census' in India is conducted every:", options:["7 years", "10 years", "5 years", "2 years"], correct: 2, explanation:"Agricultural Census (census of land holdings) is conducted every 5 years in India under the Ministry of Agriculture, collecting data on operational holdings, tenancy, and land use." },
  { id:"aeop1_102", year:2024, subject:"general-studies", question:"'Nano Urea' liquid fertilizer was developed by:", options:["IFFCO", "NRDC", "Coromandel International", "ICAR"], correct: 0, explanation:"Nano Urea liquid (40,000 ppm nitrogen, 500 ml bottle equivalent to 1 bag urea) was developed by IFFCO in 2021. It is applied as foliar spray, improving NUE and reducing conventional urea by 50%." },
  { id:"aeop1_103", year:2024, subject:"general-studies", question:"National Horticulture Mission (NHM) was launched under which Plan?", options:["11th Five Year Plan", "12th Five Year Plan", "9th Five Year Plan", "10th Five Year Plan"], correct: 3, explanation:"NHM was launched in 2005-06 under the 10th Five Year Plan to promote holistic horticulture development, double farmers' income from horticulture, and develop value chains." },
  { id:"aeop1_104", year:2024, subject:"general-studies", question:"'Rashtriya Krishi Bima Yojana' was replaced by:", options:["National Agricultural Insurance Scheme (NAIS)", "Weather-Based Crop Insurance Scheme", "MNAIS", "Pradhan Mantri Fasal Bima Yojana (PMFBY)"], correct: 3, explanation:"PMFBY (2016) replaced both NAIS and MNAIS with lower premiums, comprehensive coverage from pre-sowing to post-harvest, and faster claim settlement using technology." },
  { id:"aeop1_105", year:2024, subject:"general-studies", question:"India's first agricultural university was established at:", options:["Ludhiana", "Coimbatore", "Pantnagar (G.B. Pant University of Agriculture & Technology)", "Hyderabad"], correct: 2, explanation:"G.B. Pant University of Agriculture & Technology at Pantnagar, Uttarakhand (1960) was India's first agricultural university, modelled on US land-grant universities." },

  // ── MENTAL ABILITY & REASONING (25 Qs) ──
  { id:"aeop1_106", year:2024, subject:"general-studies", question:"If WHEAT is coded as VGDBS, what is the code for RICE?", options:["QHBD", "SHJD", "QHBD", "QHBF"], correct: 2, explanation:"Each letter is shifted one position back: W→V, H→G, E→D, A→B(wrong — A→Z), T→S. Pattern: each letter -1 in alphabet: R→Q, I→H, C→B, E→D → QHBD." },
  { id:"aeop1_107", year:2024, subject:"general-studies", question:"A farmer has 17 sheep. All but 9 die. How many are left?", options:["9", "0", "17", "8"], correct: 0, explanation:"'All but 9 die' means all except 9 die. So 9 sheep survive. This is a classic reading-comprehension reasoning question." },
  { id:"aeop1_108", year:2024, subject:"general-studies", question:"Complete the series: 2, 4, 8, 16, 32, ___", options:["72", "64", "54", "48"], correct: 1, explanation:"This is a geometric series where each term is multiplied by 2: 2×2=4, 4×2=8, 8×2=16, 16×2=32, 32×2=64." },
  { id:"aeop1_109", year:2024, subject:"general-studies", question:"Average of 5 numbers is 40. If one number is removed, average becomes 35. What is removed number?", options:["70", "60", "65", "55"], correct: 1, explanation:"Sum of 5 = 5×40=200. Sum of remaining 4 = 4×35=140. Removed number = 200-140 = 60." },
  { id:"aeop1_110", year:2024, subject:"general-studies", question:"If today is Monday, what day is it after 100 days?", options:["Friday", "Wednesday", "Thursday", "Tuesday"], correct: 0, explanation:"100 ÷ 7 = 14 weeks + 2 days remainder. Monday + 2 days = Wednesday. Wait: 100 = 14×7 + 2. Monday + 2 = Wednesday. Correct answer: Wednesday. Answer C.", correct:2, explanation:"100 ÷ 7 = 14 weeks + 2 extra days. Monday + 2 days = Wednesday." },
  { id:"aeop1_111", year:2024, subject:"general-studies", question:"A rectangular field is 200m × 150m. Cost of fencing at ₹15/m is:", options:["₹10,500", "₹22,500", "₹45,000", "₹52,500"], correct: 0, explanation:"Perimeter = 2(200+150) = 2×350 = 700m. Cost = 700 × ₹15 = ₹10,500." },
  { id:"aeop1_112", year:2024, subject:"general-studies", question:"Find the odd one out: Wheat, Rice, Maize, Mango", options:["Maize", "Rice", "Mango", "Wheat"], correct: 2, explanation:"Wheat, Rice, and Maize are cereal (grain) crops. Mango is a fruit crop — the odd one out in this group." },
  { id:"aeop1_113", year:2024, subject:"general-studies", question:"If 5 workers complete a task in 10 days, how many days will 10 workers take?", options:["10 days", "5 days", "2 days", "20 days"], correct: 1, explanation:"Work = 5 workers × 10 days = 50 worker-days. Time for 10 workers = 50 ÷ 10 = 5 days (assuming uniform productivity)." },
  { id:"aeop1_114", year:2024, subject:"general-studies", question:"Complete: Cow : Calf :: Horse : ___", options:["Colt", "Kid", "Foal", "Pony"], correct: 2, explanation:"A baby cow is called a Calf; a baby horse is called a Foal. (A Colt is a young male horse; Pony is a small adult horse; Kid is a baby goat.)" },
  { id:"aeop1_115", year:2024, subject:"general-studies", question:"Which number is missing: 1, 4, 9, 16, 25, ___?", options:["36", "42", "49", "30"], correct: 0, explanation:"The series is squares of natural numbers: 1²=1, 2²=4, 3²=9, 4²=16, 5²=25, 6²=36." },
  { id:"aeop1_116", year:2024, subject:"general-studies", question:"A train travels 60 km in 1 hour. How long to travel 210 km at same speed?", options:["3 hours", "4 hours", "2.5 hours", "3.5 hours"], correct: 3, explanation:"Time = Distance/Speed = 210/60 = 3.5 hours." },
  { id:"aeop1_117", year:2024, subject:"general-studies", question:"If 40% of a number is 80, what is the number?", options:["120", "240", "200", "160"], correct: 2, explanation:"40% of x = 80 → x = 80 × 100/40 = 200." },
  { id:"aeop1_118", year:2024, subject:"general-studies", question:"A farmer sells 50 kg rice at ₹25/kg and buys 50 kg at ₹20/kg. His profit is:", options:["₹250", "₹500", "₹200", "₹100"], correct: 0, explanation:"Revenue = 50×25 = ₹1,250. Cost = 50×20 = ₹1,000. Profit = ₹1,250 - ₹1,000 = ₹250." },
  { id:"aeop1_119", year:2024, subject:"general-studies", question:"Find the odd one out: Paddy, Wheat, Cotton, Sorghum", options:["Sorghum", "Wheat", "Paddy", "Cotton"], correct: 3, explanation:"Paddy, Wheat, and Sorghum are cereal/food grain crops. Cotton is a fibre/cash crop — the odd one out." },
  { id:"aeop1_120", year:2024, subject:"general-studies", question:"What comes next: A, C, E, G, ___?", options:["K", "H", "J", "I"], correct: 3, explanation:"The series consists of alternate letters: A(1), C(3), E(5), G(7), I(9) — every other letter of the alphabet, skipping even positions." },
  { id:"aeop1_121", year:2024, subject:"general-studies", question:"In 2 years, a sum becomes ₹1,200 at 10% simple interest. What is the principal?", options:["₹1,100", "₹800", "₹1,000", "₹900"], correct: 2, explanation:"A = P(1 + RT/100). 1200 = P(1 + 10×2/100) = P×1.2. P = 1200/1.2 = ₹1,000." },
  { id:"aeop1_122", year:2024, subject:"general-studies", question:"If FARMER = ESQLDO (each letter shifted back by 1), then CROPS = ?", options:["CRONS", "BRNOS", "DSPOT", "BQNOR"], correct: 3, explanation:"Each letter is shifted one position back: C→B, R→Q, O→N, P→O, S→R → BQNOR." },
  { id:"aeop1_123", year:2024, subject:"general-studies", question:"Select the analogy: Soil : Erosion :: Tree : ___", options:["Leaf", "Photosynthesis", "Root", "Deforestation"], correct: 3, explanation:"Just as Soil suffers Erosion (degradation), Trees suffer Deforestation (removal/destruction). Both represent degradation of a natural resource." },
  { id:"aeop1_124", year:2024, subject:"general-studies", question:"A field of 5 hectares yields 25 tonnes of rice. Yield per hectare is:", options:["5 tonnes", "6 tonnes", "4 tonnes", "3 tonnes"], correct: 0, explanation:"Yield per hectare = Total yield / Area = 25 tonnes / 5 hectares = 5 tonnes/hectare." },
  { id:"aeop1_125", year:2024, subject:"general-studies", question:"'Agriculture' : 'Farmer' :: 'Medicine' : ___", options:["Nurse", "Patient", "Doctor", "Hospital"], correct: 2, explanation:"A Farmer practises Agriculture; a Doctor practises Medicine. The relationship is practitioner:field." },
  { id:"aeop1_126", year:2024, subject:"general-studies", question:"In a row of farmers, Ramu is 5th from the left and 8th from the right. Total farmers in row:", options:["14", "13", "12", "11"], correct: 2, explanation:"Total = (position from left) + (position from right) - 1 = 5 + 8 - 1 = 12 farmers." },
  { id:"aeop1_127", year:2024, subject:"general-studies", question:"If 1 hectare = 10,000 sq metres, area of a 200m × 50m field in hectares is:", options:["2 ha", "0.5 ha", "1.5 ha", "1 ha"], correct: 3, explanation:"Area = 200 × 50 = 10,000 sq metres = 10,000/10,000 = 1 hectare." },
  { id:"aeop1_128", year:2024, subject:"general-studies", question:"Choose the correct synonym for 'Fertile':", options:["Sandy", "Barren", "Productive", "Arid"], correct: 2, explanation:"'Fertile' means capable of producing abundant vegetation or crops. Synonym: Productive. Antonyms include Barren, Arid, Infertile." },
  { id:"aeop1_129", year:2024, subject:"general-studies", question:"Complete the series: 10, 20, 40, 80, ___", options:["200", "100", "120", "160"], correct: 3, explanation:"Each term is doubled: 10×2=20, 20×2=40, 40×2=80, 80×2=160. Geometric series with ratio 2." },
  { id:"aeop1_130", year:2024, subject:"general-studies", question:"A pesticide costs ₹450 for 500ml. Cost per litre is:", options:["₹750", "₹800", "₹850", "₹900"], correct: 3, explanation:"Cost per litre = ₹450 × (1000/500) = ₹450 × 2 = ₹900 per litre." },

  // ── CURRENT AFFAIRS (20 Qs) ──
  { id:"aeop1_131", year:2024, subject:"general-studies", question:"ISRO's Chandrayaan-3 mission successfully landed on Moon's south pole in:", options:["2022", "2021", "2023", "2024"], correct: 2, explanation:"Chandrayaan-3's Vikram lander and Pragyan rover made a historic soft landing near the Moon's south polar region on 23 August 2023, making India the 4th country to land on the Moon and the first near the south pole." },
  { id:"aeop1_132", year:2024, subject:"general-studies", question:"'International Year of Millets' was declared by UN for:", options:["2021", "2023", "2024", "2022"], correct: 1, explanation:"UN declared 2023 as the International Year of Millets (IYM 2023), with India playing a leading role. The theme promoted millets as 'Shri Anna' (Smart Food) for food security and climate resilience." },
  { id:"aeop1_133", year:2024, subject:"general-studies", question:"'Viksit Bharat @2047' vision aims for India to become:", options:["A developed nation by 2047 (India's centenary of independence)", "A military superpower", "A nuclear-free state", "The world's largest economy by 2030"], correct: 0, explanation:"Viksit Bharat @2047 is PM Modi's vision to make India a developed nation by 2047 (100 years of independence), with targets in infrastructure, economy, technology, and human development." },
  { id:"aeop1_134", year:2024, subject:"general-studies", question:"India's G20 Presidency theme in 2023 was:", options:["Recover Together, Recover Stronger", "Innovate, Build, Sustain", "People, Planet, Prosperity", "Vasudhaiva Kutumbakam (One Earth, One Family, One Future)"], correct: 3, explanation:"India's G20 Presidency (December 2022 – November 2023) theme was 'Vasudhaiva Kutumbakam — One Earth, One Family, One Future', drawn from the ancient Sanskrit text Maha Upanishad." },
  { id:"aeop1_135", year:2024, subject:"general-studies", question:"'World Food Prize' 2025 was awarded to:", options:["Dr. Geoffrey Hawtin", "Dr. Mariangela Hungria", "Dr. M.S. Swaminathan", "Dr. Norman Borlaug"], correct: 1, explanation:"The 2025 World Food Prize was awarded to Dr. Mariangela Hungria (Brazil) for her work on biological nitrogen fixation through rhizobial inoculants, dramatically reducing synthetic fertilizer use." },
  { id:"aeop1_136", year:2024, subject:"general-studies", question:"'Unified Payments Interface' (UPI) was developed by:", options:["Ministry of Finance", "RBI", "NPCI (National Payments Corporation of India)", "SBI"], correct: 2, explanation:"UPI was developed by NPCI (National Payments Corporation of India) and launched in April 2016. It enables instant real-time inter-bank payments through mobile phones." },
  { id:"aeop1_137", year:2024, subject:"general-studies", question:"India's first 'Green Hydrogen' policy was announced in:", options:["2024", "2022", "2021", "2023"], correct: 1, explanation:"India's National Green Hydrogen Mission was approved on 4 January 2023, targeting 5 million metric tonnes annual green hydrogen production by 2030 for a ₹19,744 crore investment." },
  { id:"aeop1_138", year:2024, subject:"general-studies", question:"'VKSA' (Viksit Krishi Sankalp Abhiyan) is a 15-day campaign by:", options:["ICAR", "State Agriculture Departments", "Ministry of Agriculture and Farmers' Welfare", "NABARD"], correct: 2, explanation:"VKSA is a nationwide agricultural outreach campaign by Ministry of Agriculture connecting scientists, officials, and farmers to bridge research-to-field gap and promote new agricultural technologies." },
  { id:"aeop1_139", year:2024, subject:"general-studies", question:"Telangana celebrated its _____ Foundation Day on 2 June 2024:", options:["8th", "15th", "10th", "12th"], correct: 2, explanation:"Telangana was formed on 2 June 2014. On 2 June 2024, it celebrated its 10th Foundation Day (Telangana Formation Day) with various cultural and developmental programmes." },
  { id:"aeop1_140", year:2024, subject:"general-studies", question:"'Har Ghar Jal' Jal Jeevan Mission targets providing tap water connections to:", options:["50% of rural households", "Only SC/ST households", "Only BPL households", "All rural households by 2024"], correct: 3, explanation:"Jal Jeevan Mission (launched August 2019) aims to provide functional household tap connections (FHTC) to all 19.3 crore rural households by 2024, ensuring safe drinking water supply." },
  { id:"aeop1_141", year:2024, subject:"general-studies", question:"India's first 'Genome-edited' crop varieties approved in 2023 are:", options:["DRR Dhan 100 (Kamala) and Pusa DST Rice 1 — edited rice varieties", "HYV wheat varieties", "Golden Rice varieties", "Bt soybean varieties"], correct: 0, explanation:"India's first genome-edited crop varieties — DRR Dhan 100 (high-yield, early-maturing) and Pusa DST Rice 1 (drought and salinity tolerant) — were approved by the government in 2023, developed using CRISPR-Cas9." },
  { id:"aeop1_142", year:2024, subject:"general-studies", question:"The 'Agnipath' scheme is related to:", options:["Space exploration", "Renewable energy", "Agricultural modernisation", "Short-term military recruitment (4-year Agniveers)"], correct: 3, explanation:"Agnipath scheme (launched June 2022) recruits youth as 'Agniveers' for 4 years in the Indian Armed Forces (Army, Navy, Air Force). 25% may be retained as regular soldiers." },
  { id:"aeop1_143", year:2024, subject:"general-studies", question:"'PM Vishwakarma' scheme is for:", options:["Farmers", "Women SHGs", "Startups", "Traditional artisans and craftspeople (Vishwakarma community)"], correct: 3, explanation:"PM Vishwakarma scheme (launched 17 September 2023) provides training, toolkit support, and collateral-free credit (up to ₹3 lakh) to traditional artisans and craftspeople of 18 specified trades." },
  { id:"aeop1_144", year:2024, subject:"general-studies", question:"India launched its first 'Biochar Centre of Excellence' at:", options:["Punjab Agricultural University", "ICAR New Delhi", "Kanha Shanti Vanam, Hyderabad", "IIT Bombay"], correct: 2, explanation:"India's first Biochar Centre of Excellence was inaugurated at Kanha Shanti Vanam (Heartfulness Institute), Hyderabad in 2024-25, promoting biochar for soil improvement and carbon sequestration." },
  { id:"aeop1_145", year:2024, subject:"general-studies", question:"'World Environment Day' is celebrated on:", options:["5 June", "16 September", "22 April", "21 March"], correct: 0, explanation:"World Environment Day is celebrated on 5 June every year since 1974, established by the UN Environment Programme (UNEP) to raise global awareness about environmental protection." },
  { id:"aeop1_146", year:2024, subject:"general-studies", question:"India's 'One Nation One Ration Card' scheme helps:", options:["Give health insurance portability", "Farmers get MSP anywhere", "Provide free education", "Beneficiaries access PDS ration from any fair price shop in India"], correct: 3, explanation:"One Nation One Ration Card (ONORC) enables migrant workers and other beneficiaries to access PDS entitlements from any fair price shop in any state using biometric authentication." },
  { id:"aeop1_147", year:2024, subject:"general-studies", question:"'Natural Farming' initiative in Andhra Pradesh and Telangana is called:", options:["NMSA", "APCNF (Andhra Pradesh Community-managed Natural Farming)", "PKVY", "Zero-Till farming"], correct: 1, explanation:"APCNF (AP Community-managed Natural Farming) is Andhra Pradesh's large-scale Zero Budget Natural Farming initiative covering 700,000+ farmers, using Jivamrita, Bijamrita, and Waaphasa without chemical inputs." },
  { id:"aeop1_148", year:2024, subject:"general-studies", question:"'Carbon Credit' trading in agriculture is possible through:", options:["Zero tillage and organic farming that sequester CO2 in soil", "Increasing crop area", "Burning more crop residue", "Using more fertilizers"], correct: 0, explanation:"Carbon credits are earned by farming practices that sequester CO2 (zero tillage, organic farming, agroforestry). Farmers can sell these credits in carbon markets as additional income." },
  { id:"aeop1_149", year:2024, subject:"general-studies", question:"'FPO' (Farmer Producer Organisation) scheme launched by Government of India aims to form:", options:["1,000 FPOs", "50,000 FPOs", "5,000 FPOs", "10,000 FPOs"], correct: 3, explanation:"GoI launched the Formation and Promotion of 10,000 FPOs scheme in February 2020, with ₹6,865 crore budget over 5 years to improve farmers' bargaining power and market linkages." },
  { id:"aeop1_150", year:2024, subject:"general-studies", question:"TGPSC (Telangana State Public Service Commission) conducts AEO examination for recruitment to:", options:["IAS", "Village level revenue officers", "Agricultural Extension Officer posts under Dept. of Agriculture, Telangana", "KVK scientist posts"], correct: 2, explanation:"TGPSC conducts the AEO exam for direct recruitment to Agricultural Extension Officer (Group-B) posts under the Department of Agriculture, Government of Telangana, working at village level." },
] as PYQQuestion[];
